import type { Prisma } from "@prisma/client";

type Database = Pick<Prisma.TransactionClient, "representative" | "attendance">;

// A shareholder who represents attendees must use the same ballot identity as
// their representative ID. Include both IDs when reading older recorded choices.
export async function voterIdentity(db: Database, meetingId: string, voterId: string) {
  const representative = await db.representative.findUnique({ where: { id: voterId } }) ??
    await db.representative.findFirst({
      where: { shareholderId: voterId, representedBy: { some: { meetingId } } },
    });
  if (!representative) return { representative: null, voterId, aliases: [voterId] };
  return {
    representative, voterId: representative.id,
    aliases: [...new Set([representative.id, ...(representative.shareholderId ? [representative.shareholderId] : [])])],
  };
}
